import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 51 Reward for virtue","description":"学习 完成进行时与持续活动，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 51 Reward for virtue","description":"学习 完成进行时与持续活动，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 完成进行时与持续活动，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 50 Taken for a ride","link":"/life/english/new-concept/book-2/unit-03/lesson-050"},"next":{"text":"第二册：实践与进步 · Lesson 52 A pretty carpet","link":"/life/english/new-concept/book-2/unit-03/lesson-052"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 50 Taken for a ride","link":"/life/english/new-concept/book-2/unit-03/lesson-050"},"next":{"text":"第二册：实践与进步 · Lesson 52 A pretty carpet","link":"/life/english/new-concept/book-2/unit-03/lesson-052"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-051.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-051.md"}'),i={name:"life/english/new-concept/book-2/unit-03/lesson-051.md"};function s(r,e,l,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-51-reward-for-virtue" tabindex="-1">第二册：实践与进步 · Lesson 51 Reward for virtue <a class="header-anchor" href="#第二册-实践与进步-·-lesson-51-reward-for-virtue" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 51 Reward for virtue&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>控制饮食的人面对奖励食物时改变主意；练习持续努力与具体完成结果的区别。本课的语言观察是：has been avoiding 强调持续到目前的行为；has avoided three snacks 强调次数。所谓奖励不等于健康建议，这里只练习语言表达。完成学习后，请描述坚持某个生活习惯的过程，交代持续时间和一次选择。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>diet</td><td>/ˈdaɪət/</td><td>n.</td><td>饮食</td><td>a balanced diet</td></tr><tr><td>weight</td><td>/weɪt/</td><td>n.</td><td>重量；体重</td><td>gain weight</td></tr><tr><td>reward</td><td>/rɪˈwɔːd/</td><td>n.</td><td>奖励</td><td>earn a reward</td></tr><tr><td>temptation</td><td>/tempˈteɪʃən/</td><td>n.</td><td>诱惑</td><td>resist temptation</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>give up doing — 放弃做某事</li><li>for two weeks — 持续两周，不是两周前</li></ul><h2 id="语法讲解-完成进行时与持续活动" tabindex="-1">语法讲解：完成进行时与持续活动 <a class="header-anchor" href="#语法讲解-完成进行时与持续活动" aria-label="Permalink to &quot;语法讲解：完成进行时与持续活动&quot;">​</a></h2><p>现在完成进行时由 have/has been 加 -ing 构成，强调从过去持续到现在或刚刚停止且影响仍可见的活动。现在完成时更容易突出完成的数量或结果，进行形式则突出过程和时长。状态动词通常不用进行形式。for 引出时长，since 引出起点；句中有一段时间并不自动要求完成进行时，还要判断动作性质与当前是否有关联。本课应用：has been avoiding 强调持续到目前的行为；has avoided three snacks 强调次数。所谓奖励不等于健康建议，这里只练习语言表达。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Tess has been avoiding sweet snacks for two weeks.</p></blockquote><p>苔丝两周来一直尽量不吃甜食。</p><p>has been avoiding 是完成进行时，for two weeks 是持续长度，sweet snacks 是宾语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>since two weeks 错误，持续长度用 for；since two weeks ago 才引出起点。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 has been avoiding 的弱读连接，重读 two weeks，区别 for 与 four 的语境。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Tess has been avoiding sweet snacks for two weeks. Today she chose fruit at the café. She said the conversation was a better reward than cake.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>描述坚持某个生活习惯的过程，交代持续时间和一次选择。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：has been avoiding 是完成进行时，for two weeks 是持续长度，sweet snacks 是宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：since two weeks 错误，持续长度用 for；since two weeks ago 才引出起点。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 for/since：She has been practising ___ two weeks.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> for</p><p><strong>解析：</strong> two weeks 是一段时长。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>她今天在咖啡馆选了什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Fruit.</p><p><strong>解析：</strong> 示范没有说她吃了蛋糕，cake 只出现在比较中。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“自周一以来”填入：___ Monday。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> since Monday</p><p><strong>解析：</strong> since 后接起点，而不是时长。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：完成进行时与持续活动。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-050">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-052">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const k=a(i,[["render",s]]);export{u as __pageData,k as default};
